def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count recent opponent behavior with mild decay emphasis.
    # T1: detect mostly-cooperative opponents and exploit rarely/near end.
    opp_c = 0
    my_c = 0
    last_opp = history[-1][1]
    last_my = history[-1][0]

    for i in range(n):
        a, b = history[i]
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1

    # Immediate retaliation/forgiveness baseline: Tit-for-Tat-like with
    # occasional probabilistic noise and endgame adjustment.
    if n >= 100:
        return 'D'

    # If opponent has defected on the immediately previous move, usually defect,
    # but sometimes cooperate to avoid endless mutual defection.
    if last_opp == 'D':
        if last_my == 'D':
            # Mutual defection: try to restore cooperation occasionally.
            if rng.random() < 0.18:
                return 'C'
            return 'D'
        else:
            # We were exploited. Retaliate strongly, with small forgiveness.
            if rng.random() < 0.04:
                return 'C'
            return 'D'

    # Opponent cooperated last round.
    # If they are highly cooperative overall, cooperate, but defect increasingly near end.
    coopp = float(opp_c) / float(n)

    if n >= 96:
        return 'D'

    if n >= 92:
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    if n >= 85:
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    # Exploit extremely naive always-cooperators a little.
    if n >= 20 and coopp > 0.92:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Mostly cooperate against cooperative opponents.
    if coopp > 0.7:
        if rng.random() < 0.03:
            return 'D'
        return 'C'

    # Against mixed opponents, use tit-for-tat with slight forgiveness.
    if last_opp == 'C':
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    return 'C'

