def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    last_me, last_op = history[-1]
    # Estimate whether opponent is random-like vs. retaliatory
    # Count switches after our C/D
    opp_c = sum(1 for me, op in history if op == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for me, op in history if me == 'C')

    # If opponent cooperates very often, keep cooperating but watch exploitation
    if opp_c >= n - 2 and n >= 5:
        return 'C'

    # If opponent has just defected after we cooperated, punish briefly
    if last_op == 'D' and last_me == 'C':
        if n >= 3 and history[-2][1] == 'D' and history[-3][1] == 'D':
            return 'D'
        return 'D'

    # If opponent defected and we defected, sometimes test cooperation
    if last_op == 'D' and last_me == 'D':
        # reset after long mutual defection occasionally
        if n >= 4 and all(op == 'D' for _, op in history[-3:]):
            if rng.random() < 0.15:
                return 'C'
        return 'D'

    # last_op == 'C'
    if last_me == 'D':
        # we defected and got away with it; if opponent keeps cooperating, exploit mildly
        if opp_c >= n - 1:
            return 'D'
        return 'C'
    # both cooperated
    # detect if opponent seems to mirror: if our last D was followed by D and C by C
    mirror_score = 0
    mirror_total = 0
    for i in range(1, n):
        prev_me = history[i-1][0]
        curr_op = history[i][1]
        mirror_total += 1
        if (prev_me == 'C' and curr_op == 'C') or (prev_me == 'D' and curr_op == 'D'):
            mirror_score += 1
    if mirror_total > 0 and mirror_score / mirror_total > 0.85 and n >= 8:
        # Highly mirror-like: cooperate until late, then defect near the end
        if n >= 96:
            return 'D'
        return 'C'

    # Near the end, exploit a highly cooperative opponent
    if n >= 97:
        if opp_c / n > 0.8:
            return 'D'
        return 'C'

    # Default: cooperate, but occasionally probe if opponent seems too nice
    if opp_d == 0 and n >= 12 and n % 7 == 0:
        return 'D'
    return 'C'

